/// <summary>
/// The extension class for Product Receipt journal creation.
/// </summary>
[ExtensionOf(classStr(PurchPackingSlipJournalCreate))]
final class METPurchPackingSlipJournalCreate_Extension
{
}

Method.Source:
    /// <summary>
    /// Extension of create journal line method for product receipt.
    /// </summary>
    /// <param name = "_purchParmLine">The purch parm line buffer.</param>
    protected void createJournalLine(Common _purchParmLine)
    {
        #OCCRetryCount
        InventSite inventSite;
        METInventItemOrderSetup metInventItemOrderSetup;
        InventDim inventDim;
        PurchParmLine purchParmLine = _purchParmLine as PurchParmLine;

        next createJournalLine(_purchParmLine);

        try
        {
            select firstonly METAutoUpdateItemStatusUponReceipt, SiteId
                from inventSite
                join firstonly forupdate metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId == purchParmLine.ItemId
                && metInventItemOrderSetup.SiteId == inventSite.SiteId
                exists join inventDim
                where inventDim.inventDimId == purchParmLine.InventDimId
                && inventDim.InventSiteId == inventSite.SiteId;

            if (inventSite && inventSite.METAutoUpdateItemStatusUponReceipt && metInventItemOrderSetup 
                && metInventItemOrderSetup.ItemStatus == METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus)
            { 
                metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
                metInventItemOrderSetup.PublishPriceBook    = true;
                metInventItemOrderSetup.PublishPortal       = true;
                metInventItemOrderSetup.PublishHost         = true;
                metInventItemOrderSetup.update();
                //info(strFmt("@MET:ItemSiteUpdated",metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, metInventItemOrderSetup.ItemStatus));            

                // Update child items as well.
                METInventItemOrderSetup::updateChildItemSiteStatus(purchParmLine.ItemId, inventSite.SiteId);
                this.itemStatusToTransferDependSites(metInventItemOrderSetup);
            }

            // CB232_AutoSettingItemStockStatus.
            // Resets item stock status from LTNA to blank.
            METInventItemOrderSetup::resetItemStockLTNAStatus(purchParmLine.ItemId, inventSite.SiteId);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    /// <summary>
    /// Change Item status to transfer dependent sites
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    public void itemStatusToTransferDependSites(METInventItemOrderSetup _metInventItemOrderSetup)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        METInventItemOrderSetup metInventItemOrderSetupSupplySite;
        VendParameters vendParameters = VendParameters::find();
                
        while select ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain, VendId 
            from metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == _metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimView.InventSiteId == _metInventItemOrderSetup.SiteId
        {
            if (metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer && metReqItemTableInventDimView.MainWarehouseInventSiteId != _metInventItemOrderSetup.SiteId)
            {                
                select firstonly metInventItemOrderSetupSupplySite                         
                    where metInventItemOrderSetupSupplySite.ItemId      == _metInventItemOrderSetup.ItemId
                    && metInventItemOrderSetupSupplySite.SiteId   == metReqItemTableInventDimView.MainWarehouseInventSiteId;
                        
                if (metInventItemOrderSetupSupplySite)
                {
                    this.updateStatusToActive(metInventItemOrderSetupSupplySite);
                    METInventItemOrderSetup::updateChildItemSiteStatus(_metInventItemOrderSetup.ItemId, metReqItemTableInventDimView.MainWarehouseInventSiteId);
                }
            }
            else if (metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimView.VendGroup != vendParameters.METInterCompanyVendGroupId)
            {
                continue;
            }
            else
            {
                InventLocation inventLocationNDC;                

                InventLocationId warehouse = InventDim::find(METReqItemTableInventDimView.CovInventDimId).InventLocationId;
                container warehouseCon;

                if(InventLocation::find(warehouse).METNDCWarehouse)
                {
                    while select inventLocationNDC
                        where inventLocationNDC.METNDCWarehouse == NoYes::Yes
                    {
                        warehouseCon += inventLocationNDC.InventLocationId;
                    }
                }
                else
                {
                    warehouseCon += warehouse;
                }
                
                changecompany(vendParameters.METInterCompanyLegalEntity)
                {
                    ReqItemTable reqItemTableIntComp;                   

                    while select ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain, VendId
                        from reqItemTableIntComp
                        where reqItemTableIntComp.ItemId == _metInventItemOrderSetup.ItemId    
                    {
                        if(reqItemTableIntComp.ReqPOType == ReqPOType::Purch
                            && VendTable::find(reqItemTableIntComp.VendId).VendGroup == vendParameters.METInterCompanyVendGroupId)
                        {
                            for(int i =1; i<= conLen(warehouseCon); i++)
                            {
                                if(conPeek(warehouseCon, i) == VendTable::find(reqItemTableIntComp.VendId).METIntercompanyWarehouse)
                                {
                                    METInventItemOrderSetup metInventItemOrderSetupIntComp = METInventItemOrderSetup::findByItemAndSite(reqItemTableIntComp.ItemId, InventDim::find(reqItemTableIntComp.CovInventDimId).InventSiteId);
                                    this.updateStatusToActive(metInventItemOrderSetupIntComp);
                                    METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetupIntComp.ItemId, metInventItemOrderSetupIntComp.SiteId);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

/// <summary>
/// Update Item status to Active
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
public void updateStatusToActive(METInventItemOrderSetup _metInventItemOrderSetup)
{
    if(_metInventItemOrderSetup)
    {
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        _metInventItemOrderSetup.PublishPriceBook = NoYes::Yes;
        _metInventItemOrderSetup.PublishPortal = NoYes::Yes;
        _metInventItemOrderSetup.PublishHost = NoYes::Yes;
        _metInventItemOrderSetup.update();
        info(strFmt("@MET:ItemSiteUpdated",_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.SiteId, _metInventItemOrderSetup.ItemStatus));
    }
}
